const fs = await import('node:fs');
const path = await import('node:path');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath || !outputPath) throw new Error('Missing INPUT_PATH or OUTPUT_PATH');
if (!fs.existsSync(inputPath)) throw new Error('Input file not found: ' + inputPath);
const pngBuffer = fs.readFileSync(inputPath);
const mod = await import('@pdf-lib/upng');
const UPNG = mod.default || mod;
const img = UPNG.decode(pngBuffer);
const rgba = UPNG.toRGBA8(img)[0];
globalThis.width = img.width;
globalThis.height = img.height;
globalThis.rgba = rgba;

const { PDFDocument } = await import('pdf-lib');
const pdfDoc = await PDFDocument.create();
const pngImage = await pdfDoc.embedPng(globalThis.rgba);
const page = pdfDoc.addPage([globalThis.width, globalThis.height]);
page.drawImage(pngImage, { x: 0, y: 0, width: globalThis.width, height: globalThis.height });
const pdfBytes = await pdfDoc.save();
globalThis.pdfBytes = pdfBytes;

const fs = await import('node:fs');
const outputPath = process.env.OUTPUT_PATH;
fs.writeFileSync(outputPath, globalThis.pdfBytes);
const result = { pdf_path: outputPath, page_count: 1 };
console.log(JSON.stringify(result));
